// compcert_verification.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>
#include <assert.h>

#define REQUIRES(P) /* requires P */
#define ENSURES(P) /* ensures P */
#define LOOPINVARIANT(P) /* loopinvariant P */

#define MAX_SEQUENCE_LENGTH 4000
#define AMINO_ACID_COUNT 20
#define RAMACHANDRAN_SIZE 72

typedef struct {
    char code;
    float hydrophobicity;
    float volume;
    float flexibility;
    int charge;
    float helix_propensity;
    float sheet_propensity;
} amino_acid_properties_t;

typedef struct {
    float x, y, z;
    float confidence;
    int residue_index;
} coord_3d_t;

typedef struct {
    char sequence[MAX_SEQUENCE_LENGTH + 1];
    int length;
    coord_3d_t* ca_atoms;
    coord_3d_t* cb_atoms;
    float* phi_angles;
    float* psi_angles;
    float* confidence_scores;
} protein_structure_t;

protein_structure_t* allocate_protein_structure(const char* sequence) {
    REQUIRES(sequence != NULL);
    REQUIRES(strlen(sequence) <= MAX_SEQUENCE_LENGTH);
    ENSURES(return_val != NULL);

    if (sequence == NULL) return NULL;
    size_t seq_len = strlen(sequence);
    if (seq_len == 0 || seq_len > MAX_SEQUENCE_LENGTH) return NULL;

    protein_structure_t* structure = calloc(1, sizeof(protein_structure_t));
    if (structure == NULL) return NULL;

    strncpy(structure->sequence, sequence, MAX_SEQUENCE_LENGTH);
    structure->sequence[MAX_SEQUENCE_LENGTH] = '\0';
    structure->length = (int)seq_len;

    structure->ca_atoms = calloc(seq_len, sizeof(coord_3d_t));
    structure->cb_atoms = calloc(seq_len, sizeof(coord_3d_t));
    structure->phi_angles = calloc(seq_len, sizeof(float));
    structure->psi_angles = calloc(seq_len, sizeof(float));
    structure->confidence_scores = calloc(seq_len, sizeof(float));

    if (!structure->ca_atoms || !structure->cb_atoms || !structure->phi_angles || !structure->psi_angles || !structure->confidence_scores) {
        free(structure->ca_atoms);
        free(structure->cb_atoms);
        free(structure->phi_angles);
        free(structure->psi_angles);
        free(structure->confidence_scores);
        free(structure);
        return NULL;
    }

    for (int i = 0; i < structure->length; i++) {
        structure->ca_atoms[i].residue_index = i + 1;
        structure->cb_atoms[i].residue_index = i + 1;
        structure->confidence_scores[i] = 0.0f;
    }
    return structure;
}

float calculate_structure_confidence(const protein_structure_t* structure) {
    REQUIRES(structure != NULL);
    REQUIRES(structure->length > 0);
    ENSURES(return_val >= 0.0 && return_val <= 1.0);

    if (structure == NULL || structure->confidence_scores == NULL || structure->length <= 0) return 0.0f;

    double sum = 0.0;
    int valid_count = 0;

    for (int i = 0; i < structure->length; i++) {
        LOOPINVARIANT(0 <= i && i <= structure->length);
        float conf = structure->confidence_scores[i];
        if (conf >= 0.0f && conf <= 1.0f) {
            sum += conf;
            valid_count++;
        }
    }

    if (valid_count == 0) return 0.0f;
    double average = sum / valid_count;
    if (average < 0.0) return 0.0f;
    if (average > 1.0) return 1.0f;
    return (float)average;
}

bool is_allowed_conformation(float phi, float psi, char amino_acid) {
    REQUIRES(phi >= -180.0 && phi <= 180.0);
    REQUIRES(psi >= -180.0 && psi <= 180.0);

    if (phi < -180.0f || phi > 180.0f || psi < -180.0f || psi > 180.0f) return false;

    if (amino_acid == 'P') {
        return (phi >= -90.0f && phi <= -30.0f);
    }
    if (amino_acid == 'G') {
        return true;
    }

    bool alpha_region = (phi >= -90.0f && phi <= -30.0f && psi >= -75.0f && psi <= -15.0f);
    bool beta_region = (phi >= -150.0f && phi <= -90.0f && psi >= 90.0f && psi <= 150.0f);
    bool left_alpha = (phi >= 30.0f && phi <= 90.0f && psi >= 15.0f && psi <= 75.0f);

    return alpha_region || beta_region || left_alpha;
}
