# app.py
from flask import Flask, request, jsonify, render_template
from flask_socketio import SocketIO, emit
import subprocess
import threading
import uuid
import json
import os

app = Flask(__name__)
app.config['SECRET_KEY'] = 'jaded_deep_discovery_secret'
socketio = SocketIO(app, cors_allowed_origins="*")

active_jobs = {}

def run_julia_pipeline(job_id, sequence, config):
    try:
        input_data = {
            "name": f"Job_{job_id}",
            "sequences": [{"id": "A", "sequence": sequence}],
            "config": config
        }

        input_path = f"tmp/{job_id}_input.json"
        with open(input_path, 'w') as f:
            json.dump(input_data, f)

        process = subprocess.Popen(
            ["julia", "AlphaFold3_Core.jl", "--input", input_path, "--output", f"results/{job_id}"],
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True
        )

        for line in iter(process.stdout.readline, ''):
            socketio.emit('job_progress', {'job_id': job_id, 'log': line.strip()})

        process.wait()

        if process.returncode == 0:
            active_jobs[job_id]['status'] = 'completed'
            socketio.emit('job_complete', {'job_id': job_id, 'status': 'success'})
        else:
            active_jobs[job_id]['status'] = 'failed'
            err_log = process.stderr.read()
            socketio.emit('job_error', {'job_id': job_id, 'error': err_log})

    except Exception as e:
        active_jobs[job_id]['status'] = 'failed'
        socketio.emit('job_error', {'job_id': job_id, 'error': str(e)})

@app.route('/api/alphafold/predict', methods=['POST'])
def alphafold_predict():
    data = request.json
    sequence = data.get('sequence')
    msa_mode = data.get('msamode', 'mmseqs2')
    confidence = data.get('confidencecutoff', 0.8)

    if not sequence:
        return jsonify({"error": "Sequence is required"}), 400

    job_id = str(uuid.uuid4())
    active_jobs[job_id] = {'status': 'running', 'sequence': sequence}

    thread = threading.Thread(target=run_julia_pipeline, args=(job_id, sequence, data))
    thread.start()

    return jsonify({"job_id": job_id, "status": "running"}), 202

@app.route('/api/llm/prompt', methods=['POST'])
def generate_prompt():
    data = request.json
    analysis_type = data.get('analysis_type', 'structure_prediction')

    base_info = f"Protein Sequence Analysis Request\nSequence Length: {len(data['sequence'])}\nSequence: {data['sequence']}\n"

    prompts = {
        "structure_prediction": "Please provide detailed analysis including:\n1. SECONDARY STRUCTURE PREDICTION\n2. TERTIARY STRUCTURE INSIGHTS\n3. CONFIDENCE ASSESSMENT\n4. FUNCTIONAL PREDICTIONS\n5. COMPARATIVE ANALYSIS",
        "domain_identification": "Please identify and analyze protein domains:\n1. DOMAIN ARCHITECTURE\n2. DOMAIN CLASSIFICATION\n3. INTERFACE ANALYSIS\n4. FUNCTIONAL CONTEXT",
        "stability_analysis": "Please analyze protein stability factors:\n1. STABILITY FACTORS\n2. DESTABILIZING ELEMENTS\n3. MUTATION IMPACT\n4. ENVIRONMENTAL SENSITIVITY"
    }

    return jsonify({
        "prompt": base_info + prompts.get(analysis_type, prompts["structure_prediction"])
    })

if __name__ == '__main__':
    os.makedirs('tmp', exist_ok=True)
    os.makedirs('results', exist_ok=True)
    socketio.run(app, debug=True, host='0.0.0.0', port=5000)
