module AlphaFold3Network

using Flux
using CUDA
using LinearAlgebra
using Statistics
using Tullio

export InputFeatureEmbedder, MSAPairWeightedAveraging, MSAModule, ElucidatedAtomDiffusion, PairformerStack

struct TemplateEmbedder
    dim::Int
    num_templates::Int
    template_weights::Vector{Float32}
end
Flux.@functor TemplateEmbedder
function TemplateEmbedder(dim::Int; num_templates=4)
    weights = ones(Float32, num_templates) ./ num_templates
    TemplateEmbedder(dim, num_templates, weights)
end
function (te::TemplateEmbedder)(templates::AbstractArray)
    emb = zeros(Float32, size(templates,1), 1, size(templates,2), te.dim)
    if typeof(templates) <: CuArray
        emb = cu(emb)
    end
    for i in 1:min(te.num_templates, size(templates,3))
        emb .+= templates[:,:,i] .* te.template_weights[i]
    end
    return Flux.LayerNorm(te.dim)(emb)
end

struct InputFeatureEmbedder
    dim::Int
    template_embedder::TemplateEmbedder
    pos_proj::Flux.Dense
    mask_proj::Flux.Dense
    residue_proj::Flux.Dense
    chain_proj::Flux.Dense
    molecule_proj::Flux.Dense
    atom_type_proj::Flux.Dense
end
Flux.@functor InputFeatureEmbedder
function InputFeatureEmbedder(dim::Int; num_templates=4, num_molecule_ids=32)
    InputFeatureEmbedder(
        dim,
        TemplateEmbedder(dim; num_templates=num_templates),
        Flux.Dense(3, dim),
        Flux.Dense(1, dim),
        Flux.Dense(1, dim),
        Flux.Dense(1, dim),
        Flux.Dense(num_molecule_ids, dim),
        Flux.Dense(num_molecule_ids, dim)
    )
end
function (ife::InputFeatureEmbedder)(input_features::Dict{Symbol, AbstractArray})
    pos_emb = ife.pos_proj(input_features[:atom_pos])
    mask_emb = ife.mask_proj(input_features[:atom_mask])
    residue_emb = ife.residue_proj(input_features[:residue_index])
    chain_emb = ife.chain_proj(input_features[:chain_index])
    mol_emb = ife.molecule_proj(input_features[:molecule_ids])
    atom_emb = ife.atom_type_proj(input_features[:atom_types])

    return pos_emb .+ mask_emb .+ residue_emb .+ chain_emb .+ mol_emb .+ atom_emb
end

struct MSAPairWeightedAveraging
    dim::Int
    weight_proj::Flux.Dense
end
Flux.@functor MSAPairWeightedAveraging
function MSAPairWeightedAveraging(dim::Int)
    MSAPairWeightedAveraging(dim, Flux.Dense(dim, 1, bias=false))
end
function (mpwa::MSAPairWeightedAveraging)(msa::AbstractArray, pair::AbstractArray)
    weights = mpwa.weight_proj(msa)
    weights = Flux.softmax(weights, dims=2)

    @tullio out[b, i, j, d] := weights[b, s, 1] * msa[b, s, i, d] * pair[b, i, j, d]
    return dropdims(sum(out, dims=2), dims=2)
end

struct MSAModule
    dim::Int
    num_heads::Int
    msa_pair_weighted_avg::MSAPairWeightedAveraging
    attention
    transition
    norm1
    norm2
    norm3
end
Flux.@functor MSAModule
function MSAModule(dim::Int, num_heads::Int; dim_head=64)
    MSAModule(
        dim,
        num_heads,
        MSAPairWeightedAveraging(dim),
        Flux.MultiHeadAttention(dim, nheads=num_heads),
        Flux.Chain(Flux.Dense(dim, dim * 4, relu), Flux.Dense(dim * 4, dim)),
        Flux.LayerNorm(dim),
        Flux.LayerNorm(dim),
        Flux.LayerNorm(dim)
    )
end
function (msam::MSAModule)(msa::AbstractArray, pair::AbstractArray, mask=nothing)
    msa_norm1 = msam.norm1(msa)
    msa = msa .+ msam.msa_pair_weighted_avg(msa_norm1, pair)

    msa_norm2 = msam.norm2(msa)
    attn_out, _ = msam.attention(msa_norm2, msa_norm2, msa_norm2)
    msa = msa .+ attn_out

    msa_norm3 = msam.norm3(msa)
    msa = msa .+ msam.transition(msa_norm3)

    return msa
end

struct DiffusionTransformer
    pairformer
    dim::Int
    time_proj::Flux.Dense
end
Flux.@functor DiffusionTransformer
function DiffusionTransformer(dim::Int, pairformer_stack)
    DiffusionTransformer(pairformer_stack, dim, Flux.Dense(1, dim))
end
function (dt::DiffusionTransformer)(x::AbstractArray, t::AbstractArray, mask=nothing)
    t_emb = dt.time_proj(t)
    t_emb_reshaped = reshape(t_emb, size(t_emb, 1), 1, 1, size(t_emb, 2))
    x_conditioned = x .+ t_emb_reshaped
    return dt.pairformer(x_conditioned)
end

struct ElucidatedAtomDiffusion
    transformer::DiffusionTransformer
    num_samples::Int
    noise_schedule::Vector{Float32}
end
Flux.@functor ElucidatedAtomDiffusion
function ElucidatedAtomDiffusion(dim::Int, pairformer_stack, num_samples::Int)
    transformer = DiffusionTransformer(dim, pairformer_stack)
    schedule = Float32.(1 .- LinRange(0.001, 0.999, num_samples))
    ElucidatedAtomDiffusion(transformer, num_samples, schedule)
end
function (ead::ElucidatedAtomDiffusion)(x::AbstractArray, mask=nothing)
    out = x
    dev = x isa CuArray ? cu : identity
    schedule = dev(ead.noise_schedule)

    for t_val in schedule
        t_tensor = dev(fill(t_val, size(x, 1)))
        out = ead.transformer(out, t_tensor, mask)
    end
    return out
end

end # module
