            geometryAtoms.computeBoundingBox();
            geometryAtoms.boundingBox.getCenter(offset).negate();
            geometryAtoms.translate(offset.x, offset.y, offset.z);
            geometryBonds.translate(offset.x, offset.y, offset.z);

            // Render Atoms
            let positions = geometryAtoms.getAttribute('position');
            const colors = geometryAtoms.getAttribute('color');
            const position = new THREE.Vector3();
            const color = new THREE.Color();

            for (let i = 0; i < positions.count; i++) {
                position.x = positions.getX(i);
                position.y = positions.getY(i);
                position.z = positions.getZ(i);

                color.r = colors.getX(i);
                color.g = colors.getY(i);
                color.b = colors.getZ(i);

                const bFactor = json.atoms[i][9]; 
                const atomColor = this.getColorByPLDDT(bFactor);

                const material = new THREE.MeshPhongMaterial({ color: atomColor, shininess: 100 });
                const object = new THREE.Mesh(sphereGeometry, material);
                object.position.copy(position);
                object.scale.setScalar(json.atoms[i][3] === 'C' ? 1.5 : 1.2);
                this.root.add(object);
                this.atoms.push(object);
            }

            // Render Bonds
            positions = geometryBonds.getAttribute('position');
            const start = new THREE.Vector3();
            const end = new THREE.Vector3();

            for (let i = 0; i < positions.count; i += 2) {
                start.x = positions.getX(i);
                start.y = positions.getY(i);
                start.z = positions.getZ(i);

                end.x = positions.getX(i + 1);
                end.y = positions.getY(i + 1);
                end.z = positions.getZ(i + 1);

                const material = new THREE.MeshPhongMaterial({ color: 0x888888, shininess: 50 });
                const object = new THREE.Mesh(cylinderGeometry, material);
                object.position.copy(start);
                object.position.lerp(end, 0.5);
                object.scale.set(0.3, start.distanceTo(end), 0.3);
                object.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), end.clone().sub(start).normalize());
                this.root.add(object);
                this.bonds.push(object);
            }

            this.camera.position.z = geometryAtoms.boundingBox.max.z * 4;
            URL.revokeObjectURL(pdbUrl);
        });
    }

    getColorByPLDDT(score) {
        if (score > 90) return this.plddtColors.veryHigh;
        if (score > 70) return this.plddtColors.high;
        if (score > 50) return this.plddtColors.low;
        return this.plddtColors.veryLow;
    }

    onWindowResize() {
        this.width = this.container.clientWidth;
        this.height = this.container.clientHeight;
        this.camera.aspect = this.width / this.height;
        this.camera.updateProjectionMatrix();
        this.renderer.setSize(this.width, this.height);
        this.controls.handleResize();
    }

    animate() {
        requestAnimationFrame(this.animate.bind(this));
        this.controls.update();
        this.root.rotation.y += 0.001; 
        this.renderer.render(this.scene, this.camera);
    }
}
