class JobManager:
    def __init__(self):
        self.active_jobs: Dict[str, Dict[str, Any]] = {}
        self._lock = threading.Lock()

    def register_job(self, sequence: str, msa_mode: str, compute_config: dict) -> str:
        job_id = str(uuid.uuid4())
        with self._lock:
            self.active_jobs[job_id] = {
                'status': 'queued',
                'sequence': sequence,
                'msa_mode': msa_mode,
                'config': compute_config,
                'progress': 0.0
            }
        return job_id

    def update_status(self, job_id: str, status: str, progress: float = None):
        with self._lock:
            if job_id in self.active_jobs:
                self.active_jobs[job_id]['status'] = status
                if progress is not None:
                    self.active_jobs[job_id]['progress'] = progress

    def get_job(self, job_id: str):
        with self._lock:
            return self.active_jobs.get(job_id)

job_manager = JobManager()

def execute_julia_alphafold_subprocess(job_id: str, sequence: str, config: dict):
    logger.info(f"Starting Julia subprocess for job {job_id}")
    job_manager.update_status(job_id, 'running', 0.0)

    input_payload = {
        "job_id": job_id,
        "sequences": [{"id": "A", "sequence": sequence}],
        "parameters": config
    }

    input_file = os.path.join(app.config['UPLOAD_FOLDER'], f"{job_id}_input.json")
    output_dir = os.path.join(app.config['UPLOAD_FOLDER'], f"{job_id}_output")
    os.makedirs(output_dir, exist_ok=True)

    with open(input_file, 'w') as f:
        json.dump(input_payload, f)

    cmd = [
        "julia", "--project=.", "--threads=auto", "-O3",
        "AlphaFold3_Core.jl",
        "--input", input_file,
        "--output", output_dir
    ]

    try:
        process = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            bufsize=1,
            universal_newlines=True
        )

        for line in process.stdout:
            cleaned_line = line.strip()
            if cleaned_line:
                socketio.emit('job_progress', {
                    'job_id': job_id, 
                    'log': cleaned_line,
                    'timestamp': threading.current_thread().name
                }, namespace='/compute')

                if "progress:" in cleaned_line.lower():
                    try:
                        prog_val = float(cleaned_line.lower().split("progress:")[1].strip().split("%")[0])
                        job_manager.update_status(job_id, 'running', prog_val)
                    except ValueError:
                        pass

        process.wait()

        if process.returncode == 0:
            job_manager.update_status(job_id, 'completed', 100.0)
            with open(os.path.join(output_dir, f"{job_id}_metrics.json"), 'r') as mf:
                metrics = json.load(mf)
            socketio.emit('job_complete', {
                'job_id': job_id, 
                'status': 'success',
                'metrics': metrics
            }, namespace='/compute')
        else:
            stderr_output = process.stderr.read()
            logger.error(f"Julia process failed for {job_id}: {stderr_output}")
            job_manager.update_status(job_id, 'failed')
            socketio.emit('job_error', {
                'job_id': job_id, 
                'error': 'Compute process exited with non-zero status',
                'details': stderr_output
            }, namespace='/compute')

    except Exception as e:
        logger.exception(f"Exception executing Julia process for {job_id}")
        job_manager.update_status(job_id, 'failed')
        socketio.emit('job_error', {'job_id': job_id, 'error': str(e)}, namespace='/compute')

@app.route('/api/v1/jobs/submit', methods=['POST'])
def submit_job():
    try:
        data = request.get_json(force=True)
        sequence = data.get('sequence')
        if not sequence or len(sequence) < 10:
            return jsonify({"error": "Valid amino acid sequence required"}), 400

        config = {
            "msa_mode": data.get("msa_mode", "mmseqs2"),
            "iterations": int(data.get("iterations", 3)),
            "gpu_acceleration": data.get("gpu_acceleration", True),
            "diffusion_samples": int(data.get("diffusion_samples", 100))
        }

        job_id = job_manager.register_job(sequence, config['msa_mode'], config)

        thread = threading.Thread(
            target=execute_julia_alphafold_subprocess,
            args=(job_id, sequence, config),
            daemon=True
        )
        thread.start()

        return jsonify({
            "success": True,
            "job_id": job_id,
            "status": "queued",
            "message": "Job submitted successfully to compute cluster"
        }), 202

    except Exception as e:
