#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <stdbool.h>
#include <assert.h>

#define MAX_SEQUENCE_LENGTH 4000
#define RAMACHANDRAN_SIZE 72
#define MAX_CONTACTS 50000

typedef struct {
    float x;
    float y;
    float z;
    float confidence;
    int residue_index;
} coord_3d_t;

typedef struct {
    char sequence[MAX_SEQUENCE_LENGTH + 1];
    int length;
    coord_3d_t* ca_atoms;
    coord_3d_t* cb_atoms;
    float* phi_angles;
    float* psi_angles;
    float* confidence_scores;
    int contact_count;
    int contacts[MAX_CONTACTS][2];
} protein_structure_t;

protein_structure_t* allocate_protein_structure(const char* sequence) {
    if (sequence == NULL) return NULL;
    size_t seq_len = strlen(sequence);
    if (seq_len == 0 || seq_len > MAX_SEQUENCE_LENGTH) return NULL;

    protein_structure_t* structure = (protein_structure_t*)calloc(1, sizeof(protein_structure_t));
    if (structure == NULL) return NULL;

    strncpy(structure->sequence, sequence, MAX_SEQUENCE_LENGTH);
    structure->sequence[MAX_SEQUENCE_LENGTH] = '\0';
    structure->length = (int)seq_len;
    structure->contact_count = 0;

    structure->ca_atoms = (coord_3d_t*)calloc(seq_len, sizeof(coord_3d_t));
    structure->cb_atoms = (coord_3d_t*)calloc(seq_len, sizeof(coord_3d_t));
    structure->phi_angles = (float*)calloc(seq_len, sizeof(float));
    structure->psi_angles = (float*)calloc(seq_len, sizeof(float));
    structure->confidence_scores = (float*)calloc(seq_len, sizeof(float));

    if (!structure->ca_atoms || !structure->cb_atoms || !structure->phi_angles || !structure->psi_angles || !structure->confidence_scores) {
        free(structure->ca_atoms);
        free(structure->cb_atoms);
        free(structure->phi_angles);
        free(structure->psi_angles);
        free(structure->confidence_scores);
        free(structure);
        return NULL;
    }

    for (int i = 0; i < structure->length; i++) {
        structure->ca_atoms[i].residue_index = i + 1;
        structure->ca_atoms[i].confidence = 0.0f;
        structure->cb_atoms[i].residue_index = i + 1;
        structure->cb_atoms[i].confidence = 0.0f;
        structure->confidence_scores[i] = 0.0f;
    }

    return structure;
}

float calculate_rmsd(const protein_structure_t* structure, const protein_structure_t* reference) {
    if (!structure || !reference || !structure->ca_atoms || !reference->ca_atoms) return -1.0f;

    int min_length = (structure->length < reference->length) ? structure->length : reference->length;
    if (min_length <= 0) return -1.0f;

    double sum_squared_distances = 0.0;
    int valid_pairs = 0;

    for (int i = 0; i < min_length; i++) {
        coord_3d_t atom1 = structure->ca_atoms[i];
        coord_3d_t atom2 = reference->ca_atoms[i];

        if (atom1.confidence < 0.5f || atom2.confidence < 0.5f) {
            continue;
        }

        double dx = (double)atom1.x - (double)atom2.x;
        double dy = (double)atom1.y - (double)atom2.y;
        double dz = (double)atom1.z - (double)atom2.z;

        double squared_dist = (dx * dx) + (dy * dy) + (dz * dz);

        if (squared_dist >= 0.0 && squared_dist < 1e6) {
            sum_squared_distances += squared_dist;
            valid_pairs++;
        }
    }

    if (valid_pairs == 0) return -1.0f;

    double mean_squared_distance = sum_squared_distances / (double)valid_pairs;
    return (float)sqrt(mean_squared_distance);
}

void free_protein_structure(protein_structure_t* structure) {
    if (structure != NULL) {
        if (structure->ca_atoms) free(structure->ca_atoms);
        if (structure->cb_atoms) free(structure->cb_atoms);
        if (structure->phi_angles) free(structure->phi_angles);
        if (structure->psi_angles) free(structure->psi_angles);
        if (structure->confidence_scores) free(structure->confidence_scores);
        free(structure);
    }
}
